-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- LOB 유형별 시험 — SQL Server (VARBINARY(MAX) · VARCHAR(MAX) · NVARCHAR(MAX) · XML · 옛 IMAGE/TEXT/NTEXT)
--   실행:  nsql run -c <프로필> examples/lob/mssql.sql               (2019에서 확인 · STRING_AGG = 2017 이상)
--   GUI :  SQL Server 접속 탭에서 열고 전체 실행(F5)
-- ⚠ 로그인 기본 DB가 master면 아래 USE 줄을 시험용 DB로 고쳐 주석을 푼다(master에 표를 만들지 않는다).
-- 서버에 남는 것: 표 dbo.NSQLT_LOB · dbo.NSQLT_LOB_LEGACY (시험용 · 맨 끝 '정리' 절로 지운다)
-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- 기대값(네 DBMS 공통 · README 표와 같다)
--   1 IMAGE_PNG  64x64 PNG = 7,141 bytes · 머리 89504E470D0A1A0A · 3,001번째부터 8바이트 0EEE166FCB6E8BBF · 꼬리 49454E44AE426082 · MD5 0b4bfa3bc61a836e93ee34a5c18f6d97
--   2 IMAGE_BMP  8x8 BMP   =   246 bytes · 머리 424DF60000000000 · 꼬리 00FFFFC8000000FF · MD5 45d1ec3207d371a7d7cc75a3fdc6efcf
--   3 TEXT_BIG   한글 섞인 20,000줄 = 840,000자(줄당 42자 · UTF-8 1,120,000 bytes · UTF-16 1,680,000 bytes)
--                첫 줄 'LINE 000001 가나다라마바사 ABCDEFGHIJ 0123456789' · 10,000번째 줄 시작 = 419,959번째 글자 · 마지막 줄 시작 = 839,959번째 글자
--                (ASCII 판 = 줄당 45자 · 900,000자 · 10,000번째 줄 시작 449,956 · 마지막 줄 시작 899,956)
--   4 TEXT_4001  4,000자 경계를 하나 넘는 글(A × 4,000 + Z)
--   5 TEXT_32768 32,767자 경계를 하나 넘는 글(B × 32,767 + Z)
--   6 SPECIAL    탭 · CR LF · 따옴표 · 백슬래시 · 한글 · 이모지 + XML/JSON
--   7 EMPTY      길이 0(빈 값)  ·  8 NULLS  NULL — 둘은 다르게 보여야 한다
--   9 BIN_1MB    0123456789ABCDEF 반복 1,048,576 bytes(이미지 아닌 큰 이진 = Hex 보기)

-- USE M4PLAN_MS;

-- ── 0. 정리(있으면 지움) ─────────────────────────────────────────────────────────────────────
DROP TABLE IF EXISTS dbo.NSQLT_LOB;
DROP TABLE IF EXISTS dbo.NSQLT_LOB_LEGACY;

-- ── 1. 테이블 ───────────────────────────────────────────────────────────────────────────────
CREATE TABLE dbo.NSQLT_LOB (
  ID    INT            PRIMARY KEY,
  KIND  VARCHAR(30)    NOT NULL,
  NOTE  NVARCHAR(200),
  B     VARBINARY(MAX),
  C     VARCHAR(MAX),
  NC    NVARCHAR(MAX),
  X     XML
);
-- 옛 타입(앞으로 없어질 타입 · 읽기 확인용).
CREATE TABLE dbo.NSQLT_LOB_LEGACY (ID INT PRIMARY KEY, NOTE NVARCHAR(200), IMG IMAGE, TXT TEXT, NTXT NTEXT);

-- ── 2. 이미지 — 16진 글을 CONVERT(…, 2)로 바꾼다(첫 조각을 VARCHAR(MAX)로 바꿔 8,000자에서 잘리지 않게) ──
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, B)
VALUES (1, 'IMAGE_PNG', N'64x64 PNG · 7,141 bytes', CONVERT(VARBINARY(MAX),
    CAST('' AS VARCHAR(MAX))
  + ''
  + ''
  + ''
  , 2));
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, B)
VALUES (2, 'IMAGE_BMP', N'8x8 BMP · 246 bytes', );

-- ── 3. 큰 글 — NVARCHAR(MAX) = 한글 섞인 20,000줄 · VARCHAR(MAX) = ASCII 20,000줄 ─────────────────
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, NC, C)
SELECT 3, 'TEXT_BIG', N'20,000줄 · NC 840,000자(한글) · C 900,000자(ASCII)',
       STRING_AGG(CAST(N'LINE ' + RIGHT('000000' + CAST(n AS VARCHAR(6)), 6) + N' 가나다라마바사 ABCDEFGHIJ 0123456789' + NCHAR(10) AS NVARCHAR(MAX)), N'')
         WITHIN GROUP (ORDER BY n),
       STRING_AGG(CAST('LINE ' + RIGHT('000000' + CAST(n AS VARCHAR(6)), 6) + ' ABCDEFGHIJ 0123456789 abcdefghij' + CHAR(10) AS VARCHAR(MAX)), '')
         WITHIN GROUP (ORDER BY n)
FROM (SELECT TOP (20000) ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS n
        FROM sys.all_columns a CROSS JOIN sys.all_columns b) t;

-- ── 4·5. 경계 — NVARCHAR(4000) · VARCHAR(8000) 한도를 하나씩 넘는 글 ─────────────────────────────
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, NC)
VALUES (4, 'TEXT_4001', N'A × 4,000 + Z = 4,001자(NVARCHAR 4,000 경계)', REPLICATE(CAST(N'A' AS NVARCHAR(MAX)), 4000) + N'Z');
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, C)
VALUES (5, 'TEXT_32768', N'B × 32,767 + Z = 32,768자(VARCHAR 8,000 경계 넘음)', REPLICATE(CAST('B' AS VARCHAR(MAX)), 32767) + 'Z');

-- ── 6. 특수 문자 · XML ──────────────────────────────────────────────────────────────────────
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, C, NC, X)
VALUES (6, 'SPECIAL', N'탭 · CRLF · 따옴표 · 백슬래시 · 한글 · 이모지 · XML',
        'tab[' + CHAR(9) + '] crlf[' + CHAR(13) + CHAR(10) + '] quote['''' "] backslash[\] end',
        N'탭[' + NCHAR(9) + N'] 줄바꿈[' + NCHAR(13) + NCHAR(10) + N'] 한글 가나다 · 이모지 😀 · 日本語',
        N'<order id="1"><item qty="2">가나다</item><memo><![CDATA[a < b]]></memo></order>');

-- ── 7·8. 빈 값 vs NULL ─────────────────────────────────────────────────────────────────────
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, B, C, NC) VALUES (7, 'EMPTY', N'0x · '''' · N''''(길이 0)', 0x, '', N'');
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, B, C, NC) VALUES (8, 'NULLS', N'NULL', NULL, NULL, NULL);

-- ── 9. 큰 이진(이미지 아님) 1 MiB ─────────────────────────────────────────────────────────────
INSERT INTO dbo.NSQLT_LOB (ID, KIND, NOTE, B)
VALUES (9, 'BIN_1MB', N'0123456789ABCDEF 반복 · 1,048,576 bytes',
        CONVERT(VARBINARY(MAX), REPLICATE(CAST('0123456789ABCDEF' AS VARCHAR(MAX)), 131072), 2));

-- ── 10. 옛 타입 IMAGE · TEXT · NTEXT ─────────────────────────────────────────────────────────
INSERT INTO dbo.NSQLT_LOB_LEGACY (ID, NOTE, IMG, TXT, NTXT)
SELECT 1, N'IMAGE = PNG · TEXT = ASCII 900,000자 · NTEXT = 한글 840,000자', B, NULL, NULL FROM dbo.NSQLT_LOB WHERE ID = 1;
UPDATE dbo.NSQLT_LOB_LEGACY SET TXT = (SELECT C FROM dbo.NSQLT_LOB WHERE ID = 3), NTXT = (SELECT NC FROM dbo.NSQLT_LOB WHERE ID = 3) WHERE ID = 1;

-- ── 11. 판정 표 — RESULT가 전부 OK면 넣은 그대로 읽힌다 ──────────────────────────────────────────
SELECT ID, ITEM, ACTUAL, EXPECTED, CASE WHEN ACTUAL = EXPECTED THEN 'OK' ELSE 'NG' END AS RESULT FROM (
  SELECT 1 AS ID, N'PNG 길이' AS ITEM, CAST(DATALENGTH(B) AS NVARCHAR(100)) AS ACTUAL, N'7141' AS EXPECTED FROM dbo.NSQLT_LOB WHERE ID = 1 UNION ALL
  SELECT 1, N'PNG 머리 8바이트',       CONVERT(NVARCHAR(100), SUBSTRING(B, 1, 8), 2),    N'89504E470D0A1A0A' FROM dbo.NSQLT_LOB WHERE ID = 1 UNION ALL
  SELECT 1, N'PNG 3,001번째 8바이트',   CONVERT(NVARCHAR(100), SUBSTRING(B, 3001, 8), 2), N'0EEE166FCB6E8BBF' FROM dbo.NSQLT_LOB WHERE ID = 1 UNION ALL
  SELECT 1, N'PNG 꼬리 8바이트',       CONVERT(NVARCHAR(100), SUBSTRING(B, 7134, 8), 2), N'49454E44AE426082' FROM dbo.NSQLT_LOB WHERE ID = 1 UNION ALL
  SELECT 1, N'PNG MD5',                LOWER(CONVERT(NVARCHAR(100), HASHBYTES('MD5', B), 2)), N'0b4bfa3bc61a836e93ee34a5c18f6d97' FROM dbo.NSQLT_LOB WHERE ID = 1 UNION ALL
  SELECT 2, N'BMP 길이',               CAST(DATALENGTH(B) AS NVARCHAR(100)),             N'246'              FROM dbo.NSQLT_LOB WHERE ID = 2 UNION ALL
  SELECT 2, N'BMP MD5',                LOWER(CONVERT(NVARCHAR(100), HASHBYTES('MD5', B), 2)), N'45d1ec3207d371a7d7cc75a3fdc6efcf' FROM dbo.NSQLT_LOB WHERE ID = 2 UNION ALL
  SELECT 3, N'NVARCHAR 글자 수',       CAST(LEN(NC) AS NVARCHAR(100)),                   N'840000'           FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'NVARCHAR 바이트(UTF-16)', CAST(DATALENGTH(NC) AS NVARCHAR(100)),            N'1680000'          FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'NVARCHAR 첫 줄',         LEFT(NC, 11),                                     N'LINE 000001'      FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'NVARCHAR 10,000번째 줄 위치', CAST(CHARINDEX(N'LINE 010000', NC) AS NVARCHAR(100)), N'419959'  FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'NVARCHAR 마지막 줄',     SUBSTRING(NC, 839959, 41),                        N'LINE 020000 가나다라마바사 ABCDEFGHIJ 0123456789' FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'VARCHAR 글자 수',        CAST(LEN(C) AS NVARCHAR(100)),                    N'900000'           FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 3, N'VARCHAR 10,000번째 줄 위치', CAST(CHARINDEX('LINE 010000', C) AS NVARCHAR(100)), N'449956'     FROM dbo.NSQLT_LOB WHERE ID = 3 UNION ALL
  SELECT 4, N'4,001자',                CAST(LEN(NC) AS NVARCHAR(10)) + N':' + RIGHT(NC, 1), N'4001:Z'       FROM dbo.NSQLT_LOB WHERE ID = 4 UNION ALL
  SELECT 5, N'32,768자',               CAST(LEN(C) AS NVARCHAR(10)) + N':' + RIGHT(C, 1),   N'32768:Z'      FROM dbo.NSQLT_LOB WHERE ID = 5 UNION ALL
  SELECT 6, N'XML 값',                 X.value('(/order/item)[1]', 'NVARCHAR(30)'),      N'가나다'           FROM dbo.NSQLT_LOB WHERE ID = 6 UNION ALL
  SELECT 7, N'빈 값 길이(B·C·NC)',     CONCAT(DATALENGTH(B), N'·', DATALENGTH(C), N'·', DATALENGTH(NC)), N'0·0·0' FROM dbo.NSQLT_LOB WHERE ID = 7 UNION ALL
  SELECT 8, N'NULL(B·C·NC)',           CASE WHEN B IS NULL AND C IS NULL AND NC IS NULL THEN N'NULL' ELSE N'NOT NULL' END, N'NULL' FROM dbo.NSQLT_LOB WHERE ID = 8 UNION ALL
  SELECT 9, N'1 MiB 길이',             CAST(DATALENGTH(B) AS NVARCHAR(100)),             N'1048576'          FROM dbo.NSQLT_LOB WHERE ID = 9 UNION ALL
  SELECT 9, N'1 MiB 꼬리 8바이트',     CONVERT(NVARCHAR(100), SUBSTRING(B, 1048569, 8), 2), N'0123456789ABCDEF' FROM dbo.NSQLT_LOB WHERE ID = 9 UNION ALL
  SELECT 10, N'IMAGE·TEXT·NTEXT 길이', CONCAT(DATALENGTH(IMG), N'·', DATALENGTH(TXT), N'·', DATALENGTH(NTXT)), N'7141·900000·1680000' FROM dbo.NSQLT_LOB_LEGACY WHERE ID = 1
) t ORDER BY ID, ITEM;

-- ── 12. 전체 보기(GUI 값 창으로 확인) ────────────────────────────────────────────────────────
SELECT ID, KIND, NOTE, B, C, NC, X FROM dbo.NSQLT_LOB ORDER BY ID;
SELECT ID, NOTE, IMG, TXT, NTXT FROM dbo.NSQLT_LOB_LEGACY ORDER BY ID;

-- GUI에서 확인(키 입력은 사람이 · 자동 시험 아님)
--   ① 이 파일을 그 DBMS 접속 탭에서 열고 전체 실행(F5) → 마지막 결과 탭 = 판정 표(RESULT 열이 전부 OK)
--   ② 그 앞 결과 탭(전체 행)에서 LOB 셀 더블클릭 → 값 창(Value — 열)
--        1·2행 B = Image 보기(64x64 그라디언트 + 대각선 · 8x8 체크) · Hex 보기 = 머리 89 50 4E 47 / 42 4D
--        3행 = Text 보기에서 Ctrl+F 'LINE 010000' · 끝까지 스크롤 · 9행 = Hex 보기(앞부분만 + 안내가 뜨면 grid.lob_view_max_mb)
--        7행(빈 값)과 8행(NULL)이 다르게 보이는지(NULL = grid.null_text 흐림)
--   ③ 값 창 [파일로 저장] → 저장한 PNG/BMP의 MD5가 위 기대값과 같은지(PowerShell: Get-FileHash -Algorithm MD5 <파일>)
--   ④ 값 창 [파일에서 넣기]로 다른 이미지를 넣고 ✓ 적용 → 다시 조회해 길이·머리 확인(그리드 편집 · 87 §5-1)

-- ── 정리(확인이 끝나면 주석을 풀고 실행) ─────────────────────────────────────────────────────
-- DROP TABLE IF EXISTS dbo.NSQLT_LOB;
-- DROP TABLE IF EXISTS dbo.NSQLT_LOB_LEGACY;
